  "market.ping.reason.error": "撥測出錯，主機未能完成測試",
  "market.ping.rule": "判定規則：全部目標響應顯示「ICMP 可達」，部分目標響應顯示「部分超時」，全部超時顯示「無法判定」。即使大陸多地兩輪 ICMP 全超時、境外對照正常，也不能證明全 TCP 和全 UDP 被阻斷，不據此標記「IP 異常」。DNS、發包及許可權錯誤顯示檢測未完成。結果為上架快照，線路之後可能變化。",
  "market.ping.policy": "IP 被牆僅指同一 IP 在中國大陸的 ICMP、全 TCP、全 UDP 全部阻斷，且海外存取正常。單連接埠失敗、Google / YouTube / GPT / 流媒體存取異常、IP 地理庫異常均不按 IP 被牆處理，不提供免費或自動換 IP。",
  "market.ping.sellHint": "提交後由主機 Agent 以執行個體對外的 IPv4 執行真實 ICMP，不使用 TCP 代替。大陸目標全超時時追加境外對照和第二輪檢測；僅有 ICMP 結果不判定被牆，也不觸發免費或自動換 IP。完成後商品才會上架並保留快照。獨立 IPv4 使用執行個體自己的 IP 與網絡卡資訊，已關機的執行個體會先開機，測完再關機。",
